import type { PrecisionLevel } from './precision.js';

/** One additional unit: display arrangement, number scheme and exactness. */
export interface AdditionalUnit {
  /** Canonical unit name: the identity the mappings reference and the runtime registry keys units by; without `singular`/`plural` it is also the form the display line shows. */
  readonly name: string;
  /** Singular display form of the unit (AQ 1 or a unit fraction such as ½), e.g. "Packung"; absent = the name is invariant and serves for every count. Present exactly when `plural` is. */
  readonly singular?: string;
  /** Plural display form of the unit (every other AQ, including 0 and mixed numbers), e.g. "Packungen"; absent = invariant (see `singular`). */
  readonly plural?: string;
  /** Display template; placeholders <AQ> <AU> <IN> (canonical ingredient name) <INF> (its singular/plural form) <BQ> <BU> <NNBSP> (narrow no-break space). */
  readonly arrangement: string;
  /** Name of the number scheme gating this unit's additional quantities. */
  readonly numberScheme: string;
  /** True when the unit fixes the base amount (a 400 g Becher, a 200 g Block): the shown base quantity is then derived from the rounded AQ (docs/additional_quantity_specifications.md §6.3). */
  readonly exact: boolean;
}

/** One ingredient–additional-unit mapping: the factor and the per-ingredient shopping flag. */
export interface IngredientMapping {
  /** Referenced additional unit name (see ADDITIONAL_UNITS). */
  readonly au: string;
  /** Amount of base unit per one additional unit. */
  readonly factor: number;
  /** True when this ingredient is bought in this unit (the Becher of a yogurt); false when the same unit is only a recipe measure for it (the clove of garlic). At most one mapping per ingredient sets it. Drives the shopping list (docs/additional_quantity_specifications.md §3.1). */
  readonly shoppingUnit: boolean;
}

/** One ingredient in the master data: base unit, precision, reorder point and AU mappings. */
export interface IngredientEntry {
  /** Fixed base unit family of the ingredient ("g" or "ml"); the conversion factors are expressed in this unit. */
  readonly bu: string;
  /** Base-unit quantity definitely on stock directly after a shopping trip, independent of the meal plan (0 = only ever bought for a recipe; Infinity = always in stock, e.g. water). Not necessarily a ladder value. */
  readonly reorderPoint: number;
  /** Mandatory ingredient-level precision: how exact vs practical the quantities of this ingredient are displayed (docs/recipe_scaling_algorithm.md §4.1). */
  readonly precision: PrecisionLevel;
  /** Singular display form of the name (count 1 or a unit fraction such as ½), e.g. "Karotte"; absent = the name is invariant and serves for every count (Zucker, Milch). Present exactly when `plural` is. */
  readonly singular?: string;
  /** Plural display form of the name (every other count, including 0 and mixed numbers), e.g. "Karotten"; absent = invariant (see `singular`). */
  readonly plural?: string;
  /** The ingredient's additional-unit mappings; empty = bare ingredient without additional units. */
  readonly entries: readonly IngredientMapping[];
}

